<script setup>
import CCDistributionSettings from "./CCDistributionSettings.vue";
import CCChipPicker from "./CCChipPicker.vue";
import "../../styles/cc-distribution.css";
import { distributionPresets } from '../../lib/cc-distribution-presets';
import { ref, computed, onMounted, onBeforeUnmount, nextTick, watch } from 'vue';
import { request } from '../../api/http';
import { session } from '../../lib/session';
import { ccPermissions } from '../../lib/cc-permissions';
import { ccCore } from '../../api/cc-core';
import { parseLeadCsv, milestoneNames } from '../../lib/cc-journey';
import { workbook } from '../../lib/xlsx';
import { downloadCsv } from '../../lib/cc';
const emit=defineEmits(['changed']);
const schedulerStatus=ref(null);
async function checkScheduler(){await run(async()=>{schedulerStatus.value=(await request('life_slimming.api.cc_scheduler_status.run',{args:{},csrfToken:session.csrf_token})).message;});}
const moveStep=ref(1),ruleReview=ref(null),pasteText=ref(''),checks=ref(null),capacityAccepted=ref(false),capacityWarning=ref([]),checking=ref(false);
function downloadWorkbook(filename,sheets){const url=URL.createObjectURL(workbook(sheets));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function template(){downloadWorkbook('cc-lead-template.xlsx',[{name:'Leads',rows:[['name','mobile','source','branch','alt','city','interest','notes','agent']]}]);}
function readPaste(){try{const text=pasteText.value.trim();bulk.value=parseLeadCsv(text.includes('\t')?text.split('\n').map(line=>line.split('\t').map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\n'):text);checks.value=null;error.value='';}catch(e){error.value=e.message;}}
function reviewRule(){if(!rule.value.rule_name.trim()){error.value='Give the rule a name.';return;}if(!rule.value.days){error.value='Choose at least one day for this rule.';return;}ruleReview.value=JSON.parse(JSON.stringify(rule.value));error.value='';}

const tabs=['Move Leads','Auto Rules','Agents & Priority','Bulk Upload','Permissions'];
const tab=ref(0),busy=ref(false),error=ref(''),notice=ref(''),perm=ref(null),agents=ref([]),settings=ref({}),rules=ref([]),rank=ref([]),items=ref([]),selected=ref([]),lastBatch=ref(''),conflicts=ref([]),force=ref('');
const filter=ref({owners:[],stages:[],sub_statuses:[],sources:[],appt_statuses:[],milestones:[],last_results:[],overdue_only:false,include_protected:false,dormant:false,from_date:'',to_date:'',limit:200});
const toAgents=ref([]),method=ref('conversion'),clearFollowup=ref(false),note=ref('');
const methodDescriptions={equal:['⚖️ Equal share','Share leads evenly between the selected agents.'],conversion:['🏆 Best conversion','Agents converting more clients receive leads first.'],bookings:['📅 Most bookings','Prioritize agents with the most bookings.'],walkins:['🚶 Best walk-ins','Prioritize agents with more clinic visits.'],smart:['📦 Lowest load','Give leads to agents with the lightest workload.'],free_leads:['🙌 Fewest leads','Give leads to agents with the fewest open leads.'],free_fu:['🔔 Fewest follow-ups','Give leads to agents with fewer follow-ups due.']};
const lastResults=['Connected','No Response','Not Response','Not Reachable','Switch OFF','TNA','Call Disconnected','Appointment no response'];
const agentOptions=computed(()=>agents.value.map(agent=>({value:agent.agent,label:agent.name||agent.agent})));
const confirmDialog=ref(null),confirmAction=ref('move');
async function requestConfirmation(kind){confirmAction.value=kind;await nextTick();confirmDialog.value?.showModal();}
async function acceptConfirmation(){confirmDialog.value?.close();if(confirmAction.value==='undo')await undo();else if(confirmAction.value==='settings')await saveSettings();else await move();}
function selectAll(checked){selected.value=checked?items.value.map(item=>item.lead):[];}
try{lastBatch.value=localStorage.getItem('lcx_last_batch')||'';}catch{}
const methods={equal:'Round robin',conversion:'Best conversion',bookings:'Most bookings',walkins:'Best walk-ins',smart:'Lowest load',free_leads:'Fewest leads in hand',free_fu:'Fewest follow-ups due'};
const bulk=ref([]),bulkResults=ref(null),bulkMode=ref('auto'),allowDup=ref(false),bulkMeta=ref({branches:[],sources:[]}),allowedUsers=ref('');
const rule=ref(newRule()),ruleEditorOpen=ref(false);
watch(rule,()=>ruleReview.value=null,{deep:true});
watch([bulk,bulkMode,toAgents,allowDup],()=>{checks.value=null;capacityAccepted.value=false;capacityWarning.value=[];},{deep:true});
const overloaded=computed(()=>[...new Set([...capacityWarning.value,...toAgents.value.filter(id=>agents.value.find(a=>a.agent===id)?.over_cap)])]);
function newRule(){return {rule_name:'',rule_type:'Time-over New Lead',enabled:1,test_mode:1,time_value:60,time_unit:'Minutes',max_shuffles:2,days:'Mon,Tue,Wed,Thu,Fri,Sat,Sun',from_time:'10:00:00',to_time:'20:00:00',every_minutes:15,absent_mode:'Auto',statuses:[],from_agents:[],sources:[],to_agents:[],method:'Lowest Load',per_agent_limit:50};}
async function usePreset(preset,hours){editRule({...newRule(),...preset.r,...(hours?{time_value:hours,rule_name:'Hot lead overdue '+hours+' hr'}:{})});await nextTick();document.querySelector('.distribution-rule-form')?.scrollIntoView({behavior:'smooth',block:'start'});}
async function toggleRule(row){await run(async()=>{const result=await ccCore('rule_save',{rule:JSON.stringify({...row,enabled:row.enabled?0:1})});if(result.conflict?.length){editRule({...row,enabled:row.enabled?0:1});conflicts.value=result.conflict;error.value='Review the overlapping rules before enabling this rule.';return;}if(result.saved){rules.value=(await ccCore('rules')).rules;notice.value='Rule '+(row.enabled?'disabled.':'enabled.');}});}
const ruleMethodLabels={equal:'Round Robin',conversion:'Best Conversion',bookings:'Most Bookings',walkins:'Best Walk-ins',smart:'Lowest Load',free_leads:'Free Hands Leads',free_fu:'Free Hands Follow-ups'};
const ruleMethod=computed({get:()=>Object.entries(ruleMethodLabels).find(([,label])=>label===rule.value.method)?.[0]||'smart',set:value=>rule.value.method=ruleMethodLabels[value]});
const ruleDays=computed({get:()=>String(rule.value.days||'').split(',').filter(Boolean),set:value=>rule.value.days=value.join(',')});
const ruleExplanation=computed(()=>`${rule.value.rule_type==='Absent Agent'?(rule.value.absent_mode==='Manual'?'List absent agents’ due follow-ups for the team lead':'Share absent agents’ due follow-ups'):`${rule.value.rule_type} after ${rule.value.time_value} ${rule.value.time_unit}`} · ${rule.value.method}. Runs ${rule.value.days||'on no selected days'}, ${String(rule.value.from_time).slice(0,5)}–${String(rule.value.to_time).slice(0,5)}, every ${rule.value.every_minutes} minutes. Maximum ${rule.value.max_shuffles} moves per lead. ${rule.value.test_mode?'TEST mode: nothing moves yet.':'LIVE mode: eligible leads can move.'}`);
const ruleRank=ref([]),ruleRankBusy=ref(false);let ruleRankTimer,ruleRankController,ruleRankKey='';
async function loadRuleRank(){
  const recipients=rule.value.to_agents.length?rule.value.to_agents:agents.value.filter(agent=>agent.checked_in).map(agent=>agent.agent);
  const key=JSON.stringify([recipients.slice().sort(),ruleMethod.value]);if(key===ruleRankKey)return;
  ruleRankController?.abort();if(!recipients.length){ruleRank.value=[];ruleRankBusy.value=false;return;}
  const controller=new AbortController();ruleRankController=controller;ruleRankBusy.value=true;
  try{const result=await ccCore('rank',{agents:JSON.stringify(recipients),method:ruleMethod.value},controller.signal);if(!controller.signal.aborted){ruleRank.value=result.rows||[];ruleRankKey=key;}}catch(e){if(!controller.signal.aborted)error.value=e.message;}finally{if(ruleRankController===controller)ruleRankBusy.value=false;}
}
watch([()=>rule.value.to_agents.join('|'),ruleMethod,tab,()=>agents.value.length,ruleEditorOpen],()=>{clearTimeout(ruleRankTimer);if(tab.value===1&&ruleEditorOpen.value)ruleRankTimer=setTimeout(loadRuleRank,200);else ruleRankController?.abort();});
onBeforeUnmount(()=>{clearTimeout(ruleRankTimer);ruleRankController?.abort();});
const ruleTypes=['Time-over New Lead','Time-over Follow-up','Absent Agent','Hot Lead Overdue','Visited Not Booked'];
const statuses=['Appointment Booked','Walked In & Booked','Very Positive','Existing Client','Call & Confirm','Callback: Scheduled','Price Negotiation','Out Station','Get Back','Walked In: Not Booked','Joined Competition','Not interested','No Response','Invalid Number','Junk/Wrong Call','Lead','Not Reachable','Switch OFF','TNA','Not in Service','Call Disconnected','NID','Appointment no response','Other clinic','Job enquiry','Wrong number','Not Enquired','Do Not Contact','Franchise Lead'];
const distributionRules=computed(()=>rules.value.filter(r=>!['Permissions','Settings'].includes(r.rule_type)));
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function load(refresh=false){await run(async()=>{const p=await ccPermissions(refresh===true);perm.value=p;if(!p.can_move)return;const [a,r,m]=await Promise.all([ccCore('agents'),ccCore('rules'),ccCore('bulk_meta')]);agents.value=a.agents;settings.value=a.settings;rules.value=r.rules;bulkMeta.value=m;allowedUsers.value=p.movers.join('\n');});}
onMounted(()=>load());
function list(value){if(Array.isArray(value))return value;try{return JSON.parse(value||'[]');}catch{return String(value||'').split(',').map(v=>v.trim()).filter(Boolean);}}
function editRule(value){ruleEditorOpen.value=true;force.value='';rule.value={...newRule(),...value};for(const key of ['statuses','from_agents','sources','to_agents'])rule.value[key]=list(value[key]);conflicts.value=[];}
async function preview(){await run(async()=>{const args=Object.fromEntries(Object.entries(filter.value).map(([k,v])=>[k,Array.isArray(v)?JSON.stringify(v):typeof v==='boolean'?+v:v]));const result=await ccCore('dist_preview',args);items.value=result.items;selected.value=result.items.map(i=>i.lead);notice.value=result.count+' eligible leads. Review the list before moving.';moveStep.value=2;});}
async function move(){await run(async()=>{if(!selected.value.length||!toAgents.value.length)throw new Error('Select leads and receiving agents.');const data=await ccCore('dist_move',{leads:JSON.stringify(selected.value),to_agents:JSON.stringify(toAgents.value),method:method.value,clear_followup:+clearFollowup.value,note:note.value,accept_capacity:+capacityAccepted.value});if(data.capacity_warning){capacityWarning.value=data.capacity_warning;return;}lastBatch.value=data.batch;try{localStorage.setItem('lcx_last_batch',data.batch);}catch{}moveStep.value=1;notice.value=data.count+' leads moved.';items.value=[];selected.value=[];emit('changed');});}
async function undo(){await run(async()=>{const result=await ccCore('dist_undo',{batch:lastBatch.value});notice.value=result.undone+' leads moved back.';lastBatch.value='';try{localStorage.removeItem('lcx_last_batch');}catch{}emit('changed');});}
async function saveRule(){await run(async()=>{if(!rule.value.rule_name.trim())throw new Error('Give the rule a name.');const result=await ccCore('rule_save',{rule:JSON.stringify(ruleReview.value||rule.value),force:force.value});conflicts.value=result.conflict||[];if(result.saved){ruleEditorOpen.value=false;notice.value='Rule saved'+(rule.value.test_mode?' in test mode.':'.');rules.value=(await ccCore('rules')).rules;rule.value=newRule();ruleReview.value=null;force.value='';} });}
const rankBusy=ref(false);let rankTimer,rankController,rankKey='';
async function ranking(refresh=true){
  const recipients=tab.value===2?agents.value.map(agent=>agent.agent):toAgents.value;
  const key=JSON.stringify([recipients.slice().sort(),method.value]);
  if(!recipients.length){rankController?.abort();rankBusy.value=false;rank.value=[];rankKey='';return;}
  if(!refresh&&key===rankKey)return;
  rankController?.abort();const controller=new AbortController();rankController=controller;rankBusy.value=true;
  try{const data=await ccCore('rank',{agents:JSON.stringify(recipients),method:method.value},controller.signal);if(!controller.signal.aborted){rank.value=data.rows||[];rankKey=key;}}
  catch(e){if(!controller.signal.aborted)error.value=e.message;}finally{if(rankController===controller)rankBusy.value=false;}
}
watch([()=>toAgents.value.join('|'),method,moveStep,tab],()=>{clearTimeout(rankTimer);if(moveStep.value===3||tab.value===2)rankTimer=setTimeout(()=>ranking(false),200);});
onBeforeUnmount(()=>{clearTimeout(rankTimer);rankController?.abort();});
async function fileChanged(event){error.value='';bulkResults.value=null;const file=event.target.files?.[0];try{if(file?.size>2000000)throw new Error('Choose a file smaller than 2 MB.');if(file?.name.toLowerCase().endsWith('.xlsx')){busy.value=true;const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const response=await request('life_slimming.api.cc_bulk_upload.preview',{args:{content:btoa(binary)},csrfToken:session.csrf_token});bulk.value=response.message.rows;}else bulk.value=file?parseLeadCsv(await file.text()):[];}catch(e){error.value=e.message;bulk.value=[];}finally{busy.value=false;event.target.value='';}}
async function saveSettings(){await run(async()=>{settings.value=(await ccCore('settings_save',{settings:JSON.stringify(settings.value)})).settings;notice.value='Settings saved.';});}
async function preflight(){await run(async()=>{checks.value=await ccCore('bulk_check',{rows:JSON.stringify(bulk.value),mode:bulkMode.value,to_agents:JSON.stringify(toAgents.value),allow_dup:+allowDup.value});});}
async function upload(){await run(async()=>{if(!bulk.value.length)throw new Error('Choose a CSV file first.');if(['agent','split','rank'].includes(bulkMode.value)&&!toAgents.value.length)throw new Error('Choose receiving agents.');bulkResults.value=await ccCore('bulk_create',{rows:JSON.stringify(bulk.value),mode:bulkMode.value,to_agents:JSON.stringify(toAgents.value),method:method.value,allow_dup:+allowDup.value,accept_capacity:+capacityAccepted.value});if(bulkResults.value.capacity_warning){capacityWarning.value=bulkResults.value.capacity_warning;return;}if(bulkResults.value.validation_failed){checks.value=bulkResults.value;error.value='Resolve the invalid rows before creating leads.';return;}notice.value=bulkResults.value.created+' leads created.';bulk.value=[];emit('changed');});}
async function savePermissions(){await run(async()=>{const result=await ccCore('rule_save',{rule:JSON.stringify({rule_name:'Who can move leads',rule_type:'Permissions',enabled:1,test_mode:0,allowed_users:allowedUsers.value.split(/[\n,]/).map(s=>s.trim()).filter(Boolean)})});if(result.saved)notice.value='Permissions saved.';});}
function exportPreview(){downloadWorkbook('cc-distribution-preview.xlsx',[{name:'Leads',rows:[['Lead','Owner','Milestone','Last call','Unreachable in a row','Next action','Due','Sub status','Appointment'],...items.value.map(r=>[r.lead,agents.value.find(a=>a.agent===r.owner)?.name||r.owner,r.milestone,r.last_call_result,r.unreachable_streak,r.next_action,r.next_action_due,r.sub_status,r.appt_status])]}]);}
</script>
<template>
<section class="card cc-distribution"><header class="card-hdr">🔀 Lead Distribution <button class="btn btn-gy btn-sm" :disabled="busy" @click="load(true)">Refresh</button></header>
<div class="card-body"><p v-if="error" role="alert" class="cc-error">{{error}}</p><p v-if="notice" role="status" class="cc-success">{{notice}}</p><p v-if="busy" role="status">Working…</p><p v-if="perm&&!perm.can_move">You do not have permission to distribute leads.</p>
<template v-if="perm?.can_move"><nav class="distribution-tabs" aria-label="Lead distribution"><button v-for="(label,i) in tabs" :key="label" class="btn btn-sm" :aria-pressed="tab===i" @click="tab=i">{{label}}</button></nav>
<div v-if="tab===0" class="lcx-how"><b class="t">How to move leads (3 steps)</b><ol><li><b>Find the leads</b> — choose filters. Leave a box empty for all.</li><li><b>Check the list</b> — untick any lead you want to keep where it is.</li><li><b>Choose who gets them</b> — select agents and how to share. You can undo the whole move.</li></ol><small>Upcoming booked appointments, joined clients, DNC, Lost and Invalid leads are protected from moves.</small></div>
<nav v-if="tab===0" class="distribution-steps" aria-label="Move lead steps"><button v-for="(label,i) in ['1 · Find the leads','2 · Check the list','3 · Choose who gets them']" :key="label" :disabled="i>0&&!items.length" :aria-current="moveStep===i+1?'step':undefined" @click="moveStep=i+1">{{label}}</button></nav>
<section v-if="tab===0&&moveStep===1" class="lcx-step"><h4><i>1</i>Find the leads <small>Tick filters · leave a box empty for all</small></h4><div class="bd"><div class="lcx-grid">
  <CCChipPicker v-model="filter.owners" label="Present agent" :options="agentOptions" help="Find leads currently assigned to these agents."/>
  <CCChipPicker v-model="filter.milestones" label="Client milestone" :options="milestoneNames"/>
  <CCChipPicker v-model="filter.last_results" label="Last call result" :options="lastResults"/>
  <CCChipPicker v-model="filter.sub_statuses" label="CC Sub Status" :options="statuses"/>
  <CCChipPicker v-model="filter.stages" label="CC Stage" :options="['UNTOUCHED','FOLLOW-UP','PIPELINE','SUCCESS','LOST','INVALID']"/>
  <CCChipPicker v-model="filter.appt_statuses" label="Appointment status" :options="['Not Booked','Booked','Visited','Visited Booked','Visited Not Booked','Not Visited','Cancelled']"/>
  <CCChipPicker v-model="filter.sources" label="Lead source" :options="bulkMeta.sources||[]"/>
  <div class="lcx-pk"><div class="lcx-pk-h"><b>Lead created</b></div><div class="distribution-date-range"><label>From<input v-model="filter.from_date" type="date"></label><label>To<input v-model="filter.to_date" type="date"></label></div><label class="lcx-opt"><input v-model="filter.overdue_only" type="checkbox">Follow-up overdue only</label><label class="lcx-opt"><input v-model="filter.include_protected" type="checkbox">Include protected leads in preview</label><label class="lcx-opt"><input v-model="filter.dormant" type="checkbox">💤 Dormant only (no activity {{settings.dormant_days||90}}+ days)</label><label class="lcx-opt">Max leads<input v-model.number="filter.limit" type="number" min="1" max="500" aria-label="Maximum leads"></label></div>
</div><div class="distribution-actions"><button class="btn btn-g" :disabled="busy" @click="preview">Find leads → Step 2</button><button v-if="lastBatch" class="btn btn-gy" :disabled="busy" @click="requestConfirmation('undo')">↩ Undo last move</button></div></div></section>
<section v-if="tab===0&&moveStep===2" class="lcx-step"><h4><i>2</i>Check the list <small>{{selected.length}} of {{items.length}} ticked · untick to keep a lead where it is</small></h4><div class="bd"><div class="distribution-actions"><button class="btn btn-gy" :disabled="!items.length" @click="exportPreview">⬇ Excel (with Milestone &amp; Last Call)</button></div><div class="tbl-wrap"><table><thead><tr><th><input type="checkbox" aria-label="Select all preview leads" :checked="items.length>0&&selected.length===items.length" :indeterminate="selected.length>0&&selected.length<items.length" @change="selectAll($event.target.checked)"></th><th>Lead</th><th>Now with</th><th>Flag</th><th>Last call</th><th>Next action</th></tr></thead><tbody><tr v-for="item in items" :key="item.lead"><td><input v-model="selected" type="checkbox" :value="item.lead" :aria-label="'Move '+item.lead"></td><td>{{item.lead}}</td><td>{{agents.find(a=>a.agent===item.owner)?.name||item.owner||'—'}}</td><td>{{item.milestone}}</td><td>{{item.last_call_result||'—'}}<span v-if="item.unreachable_streak"> ({{item.unreachable_streak}}×)</span></td><td>{{item.next_action}} {{item.next_action_due}}</td></tr><tr v-if="!items.length"><td colspan="6">No leads match. Remove a filter and try again.</td></tr></tbody></table></div><button class="btn btn-g" :disabled="!selected.length" @click="moveStep=3">Choose receiving agents →</button></div></section>
<section v-if="tab===0&&moveStep===3" class="lcx-step"><h4><i>3</i>Choose who gets them</h4><div class="bd"><div class="lcx-grid"><CCChipPicker v-model="toAgents" label="Give to agent(s)" :options="agentOptions"/><div class="lcx-pk"><div class="lcx-pk-h"><b>How to share</b></div><div class="lcx-cards"><label v-for="(label,key) in methods" :key="key" class="lcx-card" :class="{on:method===key}"><input v-model="method" type="radio" name="distribution-method" :value="key"><b>{{methodDescriptions[key][0]}}</b>{{methodDescriptions[key][1]}}</label></div></div><div class="lcx-pk"><div class="lcx-pk-h"><b>Who gets leads first</b><span class="lcx-pk-n">1st → last</span></div><div class="lcx-rank"><p v-if="rankBusy">Loading ranking…</p><p v-else-if="!rank.length">Pick agents to see the order.</p><div v-for="(agent,index) in rank" :key="agent.agent"><em>{{agent.rank||index+1}}</em><b>{{agent.name}}</b><small>{{method==='equal'?'Equal share':method==='smart'?agent.open+' open':`Bookings ${agent.booked||0} · Walk-ins ${agent.walkins||0} · Conv ${agent.conv||0}%`}}</small></div></div><label class="lcx-opt"><input v-model="clearFollowup" type="checkbox">Clear existing follow-up time</label><label class="lcx-opt">Note<input v-model="note" placeholder="Reason for move"></label></div></div><p class="distribution-move-summary">{{toAgents.length?`${selected.length} leads will be shared between ${toAgents.length} agents — ${methods[method]}.`:'Pick at least one receiving agent.'}}</p><button class="btn btn-g" :disabled="busy||!selected.length||!toAgents.length||(overloaded.length&&!capacityAccepted)" @click="requestConfirmation('move')">🔀 Move {{selected.length}} selected leads</button></div></section>
<div v-if="tab===3" class="distribution-fields"><CCChipPicker v-model="toAgents" label="Receiving agents" :options="agentOptions"/><label>Distribution method<select v-model="method"><option v-for="(label,key) in methods" :key="key" :value="key">{{label}}</option></select></label></div>
<div v-if="overloaded.length&&(tab===0||tab===3)" class="capacity-warning" role="alert"><strong>Workload limit exceeded</strong><p>{{overloaded.map(id=>agents.find(a=>a.agent===id)?.name||id).join(', ')}}. Check the workload before assigning more leads.</p><label><input v-model="capacityAccepted" type="checkbox"> I reviewed the workload and accept this assignment.</label></div><div v-if="tab===1"><div class="lcx-applied"><b class="t">✅ What is applied right now</b><ul><li v-for="activeRule in distributionRules.filter(row=>row.enabled)" :key="activeRule.name"><strong>{{activeRule.rule_name}}</strong> · {{activeRule.test_mode?'🧪 TEST — proposed moves only':'⚡ LIVE — eligible leads can move'}} · {{activeRule.rule_type}} · {{activeRule.time_value}} {{activeRule.time_unit}} · {{activeRule.method}}</li><li v-if="!distributionRules.some(row=>row.enabled)">No rule is switched on — nothing moves automatically.</li><li><strong>Workload limits:</strong> {{settings.cap_on?'On':'Off'}} · {{settings.cap_overdue||150}} overdue follow-ups · {{settings.cap_open||1000}} open leads.</li><li><strong>Dormant pool:</strong> no activity for {{settings.dormant_days||90}}+ days.</li></ul><small>Upcoming booked appointments, joined clients, DNC, Lost and Invalid leads are never auto-moved.</small></div><div class="lcx-how"><b class="t">How auto rules work</b><ol><li>A rule watches for new leads not called, overdue follow-ups, or absent agents.</li><li>Eligible leads move to checked-in agents allowed for that lead source.</li><li>New rules start in TEST mode. Review the preview before switching to LIVE.</li></ol></div><b class="distribution-template-heading">Quick start — tap a ready rule to fill the form</b><div class="distribution-actions"><button type="button" class="btn btn-gy" @click="editRule(newRule())">＋ Blank rule</button></div><div class="lcx-tpl"><div v-for="preset in distributionPresets" :key="preset.t" class="distribution-preset"><button type="button" @click="usePreset(preset)"><b>{{preset.t}}</b><small>Opens the form pre-filled · you check and apply</small></button><div v-if="preset.hot" class="lcx-hrs"><button v-for="hours in [1,2,3,4,5,6]" :key="hours" type="button" @click="usePreset(preset,hours)">{{hours}} hr</button><button type="button" @click="usePreset(preset,8)">N…</button></div></div></div><button class="btn btn-gy" :disabled="busy" @click="checkScheduler">Check scheduler health</button><p v-if="schedulerStatus" role="status">Last execution: {{schedulerStatus.last_execution||'Not recorded'}} · {{schedulerStatus.paused?'Paused':schedulerStatus.stale?'Execution is overdue or unverified':'Running on schedule'}}<span v-if="schedulerStatus.legacy_active"> · Migration required to switch the legacy job to the updated native runner.</span></p><p>New rules start in test mode. Test runs record the proposed moves without changing ownership.</p><div class="tbl-wrap"><table><thead><tr><th>Rule</th><th>Type</th><th>Mode</th><th>Last run</th><th>Moved</th><th></th></tr></thead><tbody><tr v-for="r in distributionRules" :key="r.name"><td>{{r.rule_name}}</td><td>{{r.rule_type}}</td><td>{{r.enabled?(r.test_mode?'Test':'Live'):'Disabled'}}</td><td>{{r.last_run}}</td><td>{{r.last_moved||0}}</td><td><button class="btn btn-gy btn-sm" @click="editRule(r)">Edit</button><button class="btn btn-gy btn-sm" :disabled="busy" @click="toggleRule(r)">{{r.enabled?'Turn off':'Turn on'}}</button><details><summary>Run details</summary><pre>{{r.last_preview||'No run recorded.'}}</pre></details></td></tr></tbody></table></div>
<CCDistributionSettings v-model="settings" :agents="agents" @save="requestConfirmation('settings')"/><form v-if="ruleEditorOpen" class="distribution-rule-form" @submit.prevent="reviewRule">
<section class="lcx-step"><h4><i>1</i>What should trigger the rule?</h4><div class="bd"><div class="lcx-cards"><label v-for="type in ruleTypes" :key="type" class="lcx-card" :class="{on:rule.rule_type===type}"><input v-model="rule.rule_type" type="radio" name="distribution-rule-type" :value="type"><b>{{type}}</b>{{({'Time-over New Lead':'A new lead has not been called within the time limit.','Time-over Follow-up':'A scheduled follow-up is overdue.','Absent Agent':'An agent is not checked in or has checked out.','Hot Lead Overdue':'A hot lead has not been called on time.','Visited Not Booked':'A client visited but did not book treatment.'})[type]}}</label></div><div class="lcx-grid distribution-rule-basics"><label class="lcx-pk">Rule name<input v-model="rule.rule_name" :readonly="!!rule.name" required maxlength="140" placeholder="Give the rule a name"></label><div v-if="rule.rule_type!=='Absent Agent'" class="lcx-pk"><b>Time limit</b><div class="distribution-date-range"><input v-model.number="rule.time_value" type="number" min="1" required aria-label="Rule time limit"><select v-model="rule.time_unit" aria-label="Rule time unit"><option>Minutes</option><option>Hours</option><option>Days</option></select></div></div><label v-else class="lcx-pk">Absent agent — what to do<select v-model="rule.absent_mode"><option value="Manual">Manual — list for TL</option><option value="Auto">Auto — share the leads</option></select></label></div></div></section>
<section class="lcx-step"><h4><i>2</i>Which leads? <small>Empty = all</small></h4><div class="bd lcx-grid"><CCChipPicker v-model="rule.from_agents" label="Only leads of these agents" :options="agentOptions"/><CCChipPicker v-model="rule.statuses" label="Only these CC Sub Statuses" :options="statuses"/><CCChipPicker v-model="rule.sources" label="Only these sources" :options="bulkMeta.sources||[]"/></div></section>
<section class="lcx-step"><h4><i>3</i>Who gets them, in what order?</h4><div class="bd lcx-grid"><CCChipPicker v-model="rule.to_agents" label="Give to (empty = all checked-in)" :options="agentOptions"/><div class="lcx-pk"><div class="lcx-pk-h"><b>Priority</b></div><div class="lcx-cards"><label v-for="(label,key) in methods" :key="key" class="lcx-card" :class="{on:ruleMethod===key}"><input v-model="ruleMethod" type="radio" name="rule-priority" :value="key"><b>{{methodDescriptions[key][0]}}</b>{{methodDescriptions[key][1]}}</label></div></div><div class="lcx-pk"><div class="lcx-pk-h"><b>Who gets leads first</b></div><div class="lcx-rank"><p v-if="ruleRankBusy">Loading ranking…</p><p v-else-if="!ruleRank.length">No checked-in agents now.</p><div v-for="(agent,index) in ruleRank" :key="agent.agent"><em>{{agent.rank||index+1}}</em><b>{{agent.name}}</b><small>Bookings {{agent.booked||0}} · Conv {{agent.conv||0}}%</small></div></div></div></div></section>
<section class="lcx-step"><h4><i>4</i>When is it allowed to run?</h4><div class="bd lcx-grid"><CCChipPicker v-model="ruleDays" label="Days" :options="['Mon','Tue','Wed','Thu','Fri','Sat','Sun']"/><div class="lcx-pk"><div class="lcx-pk-h"><b>Hours</b></div><div class="distribution-date-range"><label>From<input v-model="rule.from_time" type="time"></label><label>To<input v-model="rule.to_time" type="time"></label></div><label class="lcx-opt">Check every<input v-model.number="rule.every_minutes" type="number" min="5" aria-label="Rule frequency">minutes</label></div></div></section>
<section class="lcx-step"><h4><i>5</i>Safety &amp; switch on</h4><div class="bd"><div class="lcx-grid"><div class="lcx-pk"><label class="lcx-opt">Max auto-moves per lead<input v-model.number="rule.max_shuffles" type="number" min="1" required></label><label class="lcx-opt">Max leads per agent per run<input v-model.number="rule.per_agent_limit" type="number" min="1" max="500" required></label></div><div class="lcx-pk"><label class="lcx-opt"><input v-model="rule.enabled" type="checkbox" :true-value="1" :false-value="0"><b>Rule ON</b></label><label class="lcx-opt"><input v-model="rule.test_mode" type="checkbox" :true-value="1" :false-value="0"><b>Test Mode</b> — only show, do not move</label></div></div><div class="lcx-applied distribution-rule-summary"><b class="t">📝 What will happen</b>{{ruleExplanation}}</div><div class="distribution-actions"><button class="btn btn-g" :disabled="busy">Review rule</button><button type="button" class="btn btn-gy" @click="ruleEditorOpen=false;conflicts=[];force=''">Cancel</button></div></div></section>
<div v-if="ruleReview" class="rule-applied"><h3>What is applied</h3><p>{{ruleReview.rule_name}} · {{ruleReview.rule_type}} · wait {{ruleReview.time_value}} {{ruleReview.time_unit}}</p><p>{{ruleReview.method}} · {{ruleReview.days}} · {{ruleReview.from_time}}–{{ruleReview.to_time}} · maximum {{ruleReview.max_shuffles}} shuffles</p><p>From: {{ruleReview.from_agents.join(', ')||'All eligible agents'}} → To: {{ruleReview.to_agents.join(', ')||'Eligible checked-in agents'}}</p><strong>{{ruleReview.test_mode?'TEST MODE · no leads will move':'LIVE MODE · eligible leads can move'}}</strong><button type="button" class="btn btn-g" :disabled="busy" @click="saveRule">Accept &amp; Apply</button></div><div v-if="conflicts.length" role="alert"><p>Overlapping rules: {{conflicts.map(c=>c.rule).join(', ')}}</p><label>Resolve overlap<select v-model="force"><option value="">Choose…</option><option value="replace">Disable overlapping rules</option><option value="keep">Keep both rules</option></select></label><button type="button" class="btn btn-g" :disabled="busy||!force" @click="saveRule">Accept overlap and apply</button></div></form></div>
<div v-if="tab===2"><div class="lcx-how"><b class="t">Who gets leads first</b>Choose a priority to see the order used by the system. Conversion is booked ÷ walk-ins; show-up is walk-ins ÷ appointments.</div><div class="lcx-cards"><label v-for="(label,key) in methods" :key="key" class="lcx-card" :class="{on:method===key}"><input v-model="method" type="radio" name="agent-priority" :value="key"><b>{{methodDescriptions[key][0]}}</b>{{methodDescriptions[key][1]}}</label></div><button class="btn btn-g" :disabled="busy" @click="ranking">Calculate ranking</button><div class="tbl-wrap"><table><thead><tr><th>Agent</th><th>IN / OUT</th><th>Open</th><th>Overdue</th><th>Auto</th><th>Capacity</th></tr></thead><tbody><tr v-for="a in agents" :key="a.agent"><td>{{a.name}}</td><td>{{a.checked_in?'IN':'OUT'}}</td><td>{{a.open}}</td><td>{{a.overdue}}</td><td>{{a.auto&&!a.stopped?'On':'Stopped'}}</td><td>{{a.over_cap?'Over limit':'Available'}}</td></tr></tbody></table><table v-if="rank.length"><thead><tr><th>Rank</th><th>Agent</th><th>Appointments</th><th>Walk-ins</th><th>Booked</th><th>Conversion %</th><th>Show-up %</th><th>Score</th></tr></thead><tbody><tr v-for="a in rank" :key="a.agent"><td>{{a.rank}}</td><td>{{a.name}}</td><td>{{a.appts||0}}</td><td>{{a.walkins||0}}</td><td>{{a.booked||0}}</td><td>{{a.conv}}</td><td>{{a.showup}}</td><td>{{a.score}}</td></tr></tbody></table></div></div>
<div v-if="tab===3"><p>Excel or CSV columns: name, mobile, source, branch. Optional: alt, city, interest, notes, agent. Up to 500 rows and 2 MB.</p><button class="btn btn-gy" @click="template">Download Excel template</button><label>Paste Excel or CSV rows<textarea v-model="pasteText" rows="5" placeholder="Include the header row"></textarea></label><button class="btn btn-gy" @click="readPaste">Read pasted rows</button><input type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" :disabled="busy" aria-label="Lead Excel or CSV" @change="fileChanged"><p>{{bulk.length}} rows ready for review.</p><label>Assignment<select v-model="bulkMode"><option value="auto">Automatic assignment</option><option value="agent">One agent</option><option value="split">Split across selected agents</option><option value="rank">Use ranking</option><option value="file">Agent column in file</option></select></label><label><input v-model="allowDup" type="checkbox"> Allow duplicate mobile numbers</label><button class="btn btn-g" :disabled="busy||!bulk.length" @click="preflight">Check every row</button><p v-if="checks">{{checks.ready}} ready · {{checks.invalid}} invalid · {{checks.skipped}} duplicates skipped</p><div v-if="checks" class="tbl-wrap"><table><thead><tr><th>Row</th><th>Name</th><th>Mobile</th><th>State</th><th>Validation</th></tr></thead><tbody><tr v-for="row in checks.rows" :key="row.row"><td>{{row.row}}</td><td>{{row.name}}</td><td>••••{{String(row.mobile||'').slice(-4)}}</td><td>{{row.state}}</td><td>{{row.errors.join(' ')}} {{row.duplicate?'Duplicate: '+row.duplicate:''}}</td></tr></tbody></table></div><div class="tbl-wrap"><table v-if="bulk.length&&!checks"><thead><tr><th>Name</th><th>Mobile</th><th>Source</th><th>Branch</th></tr></thead><tbody><tr v-for="r in bulk.slice(0,30)" :key="r.row"><td>{{r.name}}</td><td>••••{{r.mobile.slice(-4)}}</td><td>{{r.source}}</td><td>{{r.branch}}</td></tr></tbody></table></div><button class="btn btn-g" :disabled="busy||!checks||checks.invalid||!checks.ready||(overloaded.length&&!capacityAccepted)" @click="upload">Create {{bulk.length}} leads</button><div v-if="bulkResults" class="tbl-wrap"><table><thead><tr><th>Row</th><th>Result</th></tr></thead><tbody><tr v-for="r in bulkResults.results" :key="r.row"><td>{{r.row}}</td><td>{{r.ok?r.lead+' · '+r.owner:r.msg}}</td></tr></tbody></table></div></div>
<div v-if="tab===4"><p>Only Bhuvan and Naren can edit this permission list.</p><label>Allowed users, one login per line<textarea v-model="allowedUsers" rows="8" :disabled="!perm.can_edit_perm"></textarea></label><button v-if="perm.can_edit_perm" class="btn btn-g" :disabled="busy" @click="savePermissions">Save permissions</button></div>
<dialog ref="confirmDialog" class="crm-distribution-confirm" aria-labelledby="distribution-confirm-title"><h2 id="distribution-confirm-title">{{confirmAction==='undo'?'Undo last move?':confirmAction==='settings'?'Apply workload settings?':`Move ${selected.length} leads?`}}</h2><template v-if="confirmAction==='move'"><p>{{selected.length}} leads → {{toAgents.map(id=>agents.find(agent=>agent.agent===id)?.name||id).join(', ')}}</p><p>Method: {{methods[method]}}</p><p>Follow-up time: {{clearFollowup?'Clear':'Keep'}}</p><p>You can undo this move later.</p></template><p v-else-if="confirmAction==='undo'">Every lead in batch {{lastBatch}} goes back to the agent it came from.</p><div v-else><p>These settings will apply to future assignments.</p><ul><li>Workload limit: {{settings.cap_on?'On':'Off'}}</li><li>Overdue: {{settings.cap_overdue}} follow-ups in {{settings.overdue_days}} days</li><li>Open leads: {{settings.cap_open}} in {{settings.open_days}} days</li><li>Dormant pool: {{settings.dormant_days}} days without activity</li><li>Senior closers: {{(settings.seniors||[]).map(id=>agents.find(agent=>agent.agent===id)?.name||id).join(', ')||'None selected'}}</li></ul></div><div class="distribution-actions"><button class="btn btn-gy" @click="confirmDialog.close()">Cancel</button><button class="btn btn-g" :disabled="busy" @click="acceptConfirmation">{{confirmAction==='undo'?'Yes, undo':confirmAction==='settings'?'Accept & apply':'Yes, move leads'}}</button></div></dialog></template></div></section>
</template>
<style scoped>.distribution-tabs,.distribution-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:14px 0}.distribution-tabs button[aria-pressed=true]{background:#16402d;color:white}.distribution-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:15px 0}.distribution-fields label,label:has(textarea){display:grid;gap:6px;font-size:12px}.distribution-fields input,.distribution-fields select,textarea{border:1px solid #d8cfb8;border-radius:7px;padding:8px;color:#214638;background:white;max-width:100%;box-sizing:border-box}select[multiple]{min-height:95px}textarea{width:100%;max-width:600px}pre{white-space:pre-wrap;max-width:450px;font-size:11px}.tbl-wrap{max-height:430px;overflow:auto}button{cursor:pointer}.distribution-steps{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.distribution-steps button[aria-current=step]{background:#16402d;color:white}.rule-applied{background:#e9f6ea;border:1px solid #438452;border-radius:10px;padding:14px;margin:14px 0}.capacity-warning{background:#fff2d9;border:1px solid #d7962c;border-radius:9px;padding:12px;margin:12px 0}</style>
